import { dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { FlatCompat } from "@eslint/eslintrc";

/**
 * ESLint 9 flat config. `eslint-config-next` still ships eslintrc-style configs,
 * so FlatCompat bridges them. Replaces `.eslintrc.json`, which ESLint 9 no
 * longer reads by default (`next lint` prompted to create one on every run).
 */
const compat = new FlatCompat({
  baseDirectory: dirname(fileURLToPath(import.meta.url)),
});

const config = [
  {
    // `next-env.d.ts` is generated by Next.js. `docs/` is the static GitHub
    // Pages site (plain browser JS, no TypeScript). Fixture trees are
    // deliberately buggy eval ground truth, and eval results are generated
    // output — neither is ours to lint.
    ignores: [
      ".next/**",
      "node_modules/**",
      "next-env.d.ts",
      "docs/**",
      "evals/fixtures/**",
      "evals/results/**",
    ],
  },
  ...compat.extends("next/core-web-vitals", "next/typescript"),
];

export default config;
